WITH filtered AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, CONCAT_WS(',', firmware, device_code) AS firmware_device_code_key FROM device_readings WHERE firmware = '1.0.3'), filtered_device_readings AS (SELECT *, pressure - temp_c AS pressure_minus_temp_c FROM filtered WHERE reading_ts >= DATE '2025-09-01' AND pressure BETWEEN 1007 AND 1012), with_windows AS (SELECT *, SUM(pressure_minus_temp_c) OVER w_running AS cumulative_pressure_minus_temp_c, LAST_VALUE(humidity, TRUE) OVER w_running AS last_known_humidity FROM filtered_device_readings WHERE temp_c <= 26 WINDOW w_running AS (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), matched_keys AS (SELECT device_code FROM with_windows EXCEPT SELECT device_code FROM device_readings WHERE reading_ts >= '2024-07-01'), verified AS (SELECT s.* FROM with_windows s JOIN matched_keys k ON s.device_code = k.device_code) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, SUM(CASE WHEN device_code = 'DV-03' THEN pressure ELSE 0 END) AS dv_03_pressure, MIN(reading_ts) AS first_reading_ts, ROUND(AVG(cumulative_pressure_minus_temp_c), 2) AS avg_cumulative_pressure_minus_temp_c, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, SIZE(COLLECT_SET(device_code)) AS num_device_codes FROM verified GROUP BY DATE_TRUNC('DAY', reading_ts) ORDER BY activity_day DESC NULLS LAST;
